import { createChart, getViewGroup } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { PiecewiseVisualMapOption } from '../../../../../src/component/visualMap/PiecewiseModel';
import Group from 'zrender/src/graphic/Group';
import Displayable from 'zrender/src/graphic/Displayable';

type PieceElInfo = {
    itemGroups: Group[]
    displayables: Displayable[]
};

function collectPieceEls(chart: EChartsType): PieceElInfo {
    const viewGroup = getViewGroup(chart, 'visualMap', 0);
    const itemGroups: Group[] = [];
    const displayables: Displayable[] = [];
    viewGroup.eachChild(function (child) {
        // Skip the background rect (added by `renderBackground`, always silent).
        if (child instanceof Group) {
            itemGroups.push(child);
            child.eachChild(function (el) {
                displayables.push(el as Displayable);
            });
        }
    });
    return { itemGroups, displayables };
}

function makeOption(selectedMode: PiecewiseVisualMapOption['selectedMode']) {
    return {
        xAxis: { data: ['a', 'b', 'c'] },
        yAxis: {},
        visualMap: [{
            type: 'piecewise',
            splitNumber: 3,
            min: 0,
            max: 30,
            selectedMode: selectedMode
        }],
        series: [{
            type: 'bar',
            data: [5, 15, 25]
        }]
    } as any;
}

describe('visualMap_piecewise_selectedMode', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart();
    });

    afterEach(function () {
        chart.dispose();
    });

    it('pieces are interactive when selectedMode is enabled', function () {
        chart.setOption(makeOption('multiple'));

        const { itemGroups, displayables } = collectPieceEls(chart);

        expect(itemGroups.length).toBeGreaterThan(0);
        expect(displayables.length).toBeGreaterThan(0);

        for (let i = 0; i < itemGroups.length; i++) {
            expect(typeof itemGroups[i].onclick).toEqual('function');
        }
        for (let i = 0; i < displayables.length; i++) {
            expect(displayables[i].cursor).toEqual('pointer');
            expect(!!displayables[i].silent).toEqual(false);
        }
    });

    it('pieces and labels are not clickable when selectedMode is false', function () {
        chart.setOption(makeOption(false));

        const { itemGroups, displayables } = collectPieceEls(chart);

        expect(itemGroups.length).toBeGreaterThan(0);
        expect(displayables.length).toBeGreaterThan(0);

        for (let i = 0; i < itemGroups.length; i++) {
            expect(itemGroups[i].onclick).toBeFalsy();
        }
        for (let i = 0; i < displayables.length; i++) {
            expect(displayables[i].cursor).not.toEqual('pointer');
            expect(displayables[i].silent).toEqual(true);
        }
    });

    it('single selectedMode keeps the interactive cursor', function () {
        chart.setOption(makeOption('single'));

        const { displayables } = collectPieceEls(chart);

        expect(displayables.length).toBeGreaterThan(0);
        for (let i = 0; i < displayables.length; i++) {
            expect(displayables[i].cursor).toEqual('pointer');
        }
    });

});

