import { createChart, getECModel } from '../../../core/utHelper';

function getView(chart: any) {
    const component = getECModel(chart).getComponent('visualMap', 0);
    return chart._componentsMap[(component as any).__viewId];
}

function run(extra: any) {
    const chart = createChart({ width: 600, height: 400 });
    chart.setOption({
        xAxis: { data: ['a', 'b', 'c'] },
        yAxis: {},
        visualMap: [Object.assign({
            type: 'continuous',
            orient: 'horizontal',
            calculable: true,
            min: 0,
            max: 100,
            itemWidth: 20,
            itemHeight: 140,
            left: 'center',
            bottom: 10
        }, extra)],
        series: [{ type: 'bar', data: [10, 50, 90] }]
    } as any);
    const view: any = getView(chart);
    const labels = view._shapes.handleLabels;
    const thumbs = view._shapes.handleThumbs;
    // eslint-disable-next-line
    console.log(JSON.stringify(extra), 'labelY=', labels.map((l: any) => l.style.y),
        'labelX=', labels.map((l: any) => l.style.x),
        'align=', labels.map((l: any) => l.style.align),
        'valign=', labels.map((l: any) => l.style.verticalAlign),
        'thumbScale=', thumbs.map((t: any) => t.scaleX),
        'thumbX=', thumbs.map((t: any) => t.x));
    chart.dispose();
}

describe('probe', function () {
    it('dump', function () {
        run({});
        run({ inRange: { symbolSize: [0, 100] } });
        run({ inRange: { symbolSize: [0, 100] }, top: 10, bottom: null });
        run({ orient: 'vertical' });
        run({ orient: 'vertical', inRange: { symbolSize: [0, 100] } });
    });
});

