import { createChart, getECModel, removeChart } from '../../../core/utHelper';
import { EChartsType } from '../../../../../src/echarts';
import { Dictionary } from 'zrender/src/core/types';

const ITEM_WIDTH = 20;
const ITEM_HEIGHT = 140;

/**
 * The handle labels live directly on the visualMap view group (they must not be
 * affected by the bar group transform), so they are read from the view shapes.
 */
function getHandleLabelPositions(chart: EChartsType, extraOption: Dictionary<unknown>) {
    chart.setOption({
        xAxis: { data: ['a', 'b', 'c'] },
        yAxis: {},
        visualMap: [Object.assign({
            type: 'continuous',
            calculable: true,
            min: 0,
            max: 100,
            itemWidth: ITEM_WIDTH,
            itemHeight: ITEM_HEIGHT,
            left: 'center',
            bottom: 10
        }, extraOption)],
        series: [{ type: 'bar', data: [10, 50, 90] }]
    } as any, true);

    const model = getECModel(chart).getComponent('visualMap', 0);
    // @ts-ignore
    const view = chart._componentsMap[(model as any).__viewId];
    const handleLabels = (view as any)._shapes.handleLabels as { style: { x: number, y: number } }[];

    expect(handleLabels.length).toEqual(2);

    return handleLabels.map(function (label) {
        return { x: label.style.x, y: label.style.y };
    });
}

describe('visualMap_continuous_handleLabel', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart({ width: 600, height: 400 });
    });

    afterEach(function () {
        removeChart(chart);
    });

    it('horizontal handle labels keep clear of the bar when symbolSize is mapped', function () {
        const positions = getHandleLabelPositions(chart, {
            orient: 'horizontal',
            inRange: { symbolSize: [0, 100] }
        });

        // The bar occupies |y| from 0 to ITEM_WIDTH (perpendicular to a horizontal bar).
        // Both handle labels must be placed beyond the bar, with room for the text itself.
        for (let i = 0; i < positions.length; i++) {
            expect(Math.abs(positions[i].y) - ITEM_WIDTH).toBeGreaterThan(ITEM_WIDTH * 0.4);
        }
    });

    it('horizontal handle labels are unchanged when symbolSize is not mapped', function () {
        const positions = getHandleLabelPositions(chart, { orient: 'horizontal' });

        // Constant symbol size means no extra offset at all: both labels stay symmetric.
        expect(positions[0].y).toBeCloseTo(positions[1].y, 6);
    });

    it('horizontal label at the maximum end is not offset', function () {
        const plain = getHandleLabelPositions(chart, { orient: 'horizontal' });
        const mapped = getHandleLabelPositions(chart, {
            orient: 'horizontal',
            inRange: { symbolSize: [0, 100] }
        });

        // Offset reaches 0 at the "maximum" position, so it must not move.
        expect(mapped[1].y).toBeCloseTo(plain[1].y, 6);
        // ... while the "minimum" position is pushed away from the bar.
        expect(Math.abs(mapped[0].y)).toBeGreaterThan(Math.abs(plain[0].y) - ITEM_WIDTH);
        expect(Math.abs(mapped[0].y)).toBeGreaterThan(ITEM_WIDTH);
    });

    it('vertical handle labels are not affected', function () {
        const plain = getHandleLabelPositions(chart, { orient: 'vertical' });
        const mapped = getHandleLabelPositions(chart, {
            orient: 'vertical',
            inRange: { symbolSize: [0, 100] }
        });

        expect(plain[0].y).toBeCloseTo(0, 6);
        expect(plain[1].y).toBeCloseTo(-ITEM_HEIGHT, 6);
        // The vertical layout must keep its current behaviour.
        expect(mapped[0].y).toBeCloseTo(plain[0].y, 6);
        expect(mapped[1].y).toBeCloseTo(plain[1].y, 6);
    });

});

